    score += (post_residual as f64) * 0.08 * remaining;

    // Open‑bins pressure – more open bins amplify the residual penalty,
    // especially when we are late and have fewer items left.
    let open_pen = (open_bins_count as f64)
        * (post_residual as f64 / bin_capacity as f64)
        * 0.02
        * (1.0 + remaining);
