        let excess = post_residual as f64 - mean_residual;
        score += excess * 0.5 * (1.0 - remaining).powi(2);
    } else {
        // Small bonus for under‑average residuals
        let deficit = mean_residual - post_residual as f64;
        score -= deficit * 0.3;
    }

    // Gap‑closeness bonus: if the gap after placement is less than 5% of the bin,
    // give a substantial bonus (capped at 12.0).
    let gap = (bin_residual as f64 - item_size as f64).max(0.0);
    let gap_ratio = gap / bin_capacity as f64;
    if gap_ratio < 0.05 {
        let bonus = (0.05 - gap_ratio) * 250.0;
        score -= bonus.min(12.0);
    }

    // Fitting‑bins pressure – if this is the only bin that can hold the item,
    // give a moderate bonus. If many bins can fit, add a slight penalty
    // to encourage the tighter one.
    if fitting_bins_count == 1 {
        score -= 5.0;
    } else if fitting_bins_count > 1 {
        score += 0.3 * (fitting_bins_count as f64 - 1.0);
    }

    // New‑bin candidate handling – prefer opening a new bin only if the item
    // would occupy a large portion of the bin; otherwise, penalise it.
