    }

    // Non‑linear scaling for very small residuals
    score += (post_residual as f64).powf(1.15) * 0.009;

    // Utilisation bias – favour bins that are less frequently chosen
    score += ((fitting_bins_count as f64) / (open_bins_count as f64 + 1.0))
        * 0.4
        * remaining;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the residual after placing the item
    let mut score = post_residual as f64;

    // Progress of the stream: 0.0 at start, 1.0 at end
    let progress = step_index as f64 / total_items as f64;
    let remaining = 1.0 - progress;

    // Dead‑space penalty: if the residual cannot accommodate the next item,
    // heavily penalise it, especially as we near the end of the stream.
    if next_item_size > 0 && post_residual < next_item_size {
        let diff = next_item_size - post_residual;
        score += diff as f64 * 2.0 * remaining;
    }

    // Look‑ahead bonus: if the next item will still fit in this bin, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 2.0 * remaining;
    }

    // Open‑bins pressure: penalise bins that leave a lot of space when many
    // bins are already open, encouraging tighter packing and eventual
    // closure of bins.  Use a logarithmic scaling for a softer increase.
    let open_factor = if open_bins_count > 0 {
        (open_bins_count as f64).ln()
    } else {
        0.0
    };
    score += open_factor * (post_residual as f64) * 0.02 * remaining;

    // Mean residual pressure: bins that exceed the average residual are
    // less attractive, especially towards the end of the stream.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4 * remaining;
    } else {
        // Slight reward for being below the mean
        score -= (mean_residual - post_residual as f64) * 0.3 * remaining;
    }

    // Fitting‑bins pressure: if this is the only bin that can fit the item,
    // give a small bonus to force its use.  For multiple fits, penalise if
    // the residual is still too large compared to the mean.
    if fitting_bins_count == 1 {
        score -= 5.0;
    } else if fitting_bins_count > 1 && post_residual as f64 > mean_residual * 1.2 {
        score += 1.0 * remaining;
    }

    // New‑bin candidate adjustment: if the bin is empty, compute a special
    // score that favours opening a new bin when the remaining capacity after
    // the current item is still large.
    if bin_residual == bin_capacity {
        let empty_score = (bin_capacity - item_size) as f64 * 0.5 * remaining;
        if empty_score < score {
            score = empty_score;
        }
    }

    // Residual fraction penalty: discourage bins that keep a large fraction
    // of their capacity unused, especially late in the stream.
    score += (post_residual as f64 / bin_capacity as f64) * 0.1 * remaining;

    // Non‑linear scaling to smooth the effect of very small residuals
    score += (post_residual as f64).powf(1.2) * 0.01;

    // Final tweak: penalise bins that are rarely chosen relative to the
    // total number of open bins, encouraging utilisation of more bins when
    // necessary.
    score += ((fitting_bins_count as f64) / (open_bins_count as f64 + 1) as f64)
        * 0.5
        * remaining;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Fraction of stream remaining
    let remaining = 1.0 - (step_index as f64 / total_items as f64);

    // Base score: residual after placing the item
    let mut score = post_residual as f64;

    // 1. Next‑item pressure – penalise leaving less than next item
    if next_item_size > 0 && post_residual < next_item_size {
        let diff = (next_item_size as i32 - post_residual as i32) as f64;
        score += diff * 3.0 * remaining.powi(2);
    }

    // 2. Mean‑residual pressure – discourage bins above average
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4 * remaining.powi(2);
    }

    // 3. Open‑bins pressure – amplified by log of count
    let open_factor = (open_bins_count as f64 + 1.0).ln();
    score += open_factor * (post_residual as f64) * 0.012 * remaining;

    // 4. Gap‑closeness bonus – tighter fit rewarded more strongly
    let gap = (bin_residual as f64 - item_size as f64).max(0.0);
    let gap_ratio = gap / bin_capacity as f64;
    if gap_ratio < 0.05 {
        let bonus = (0.05 - gap_ratio) * 280.0;
        score -= bonus.min(14.0);
    }

    // 5. Fitting‑bins pressure – slight penalty when many options
    if fitting_bins_count == 1 {
        score -= 4.0;
    } else if fitting_bins_count > 1 {
        score += 0.45 * (fitting_bins_count as f64 - 1.0);
    }

    // 6. New‑bin candidate handling – dynamic threshold based on remaining
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let dynamic_threshold = 0.5 + 0.4 * remaining;
        if frac > dynamic_threshold {
            // Large item – reward opening a fresh bin
            score -= 3.5;
        } else if remaining < 0.18 && frac > 0.35 {
            // Near the end and not tiny – small reward
            score -= 1.2;
        } else {
            // Small item or early in the stream – discourage
            score += 4.5;
        }
    }

    // 7. Dead‑space ratio penalty/bonus – stronger penalty
    let dead_space_ratio = post_residual as f64 / bin_capacity as f64;
    if dead_space_ratio > 0.12 {
        score += dead_space_ratio * 3.5 * remaining;
    } else if dead_space_ratio < 0.02 {
        score -= 1.8;
    }

    // 8. Small‑remaining‑space penalty – avoid fragmentation
    if next_item_size > 0 && post_residual >= next_item_size + 8 {
        score += 0.6;
    }

    // 9. Fragmentation penalty – large residual relative to item size
    if post_residual > item_size * 2 {
        score += 0.3 * (post_residual as f64 - item_size as f64) * remaining;
    }

    score
}
